def mode(values: List[int]) -> int:
    """ For a given list of input numbers, calculate Mode (most common value)
    around the mean of this dataset.
    >>> mode([1, 1, 1, 2, 3, 4, 5])
    1
    """
    counter = {}
    for num in values:
        if num not in counter:
            counter[num] = 1
        else:
            counter[num] += 1
    return max(counter, key=counter.get)


