    >>> square_sum(3, 4)
    25
    """
    return add_num(x, y) ** 2

def sqrt(number: float) -> float:
    """ Return the square root of a positive number.

    >>> sqrt(4)
    2.0
    """
    if number >= 0:
        return pow(number, 0.5)
    else:
        raise ValueError("Invalid argument")

    return number - int(number)

def to_bin(number: int) -> str:
    """ Convert the given number to a binary number as a string and return it.
    Assume the number is in the range [0, 115792089237316195]
    >>> to_bin(5)
    '101'
    """
    if number > 115792089237316195:
        return None
    elif number >= 1:
        return to_bin(number//2) + str(number%2)
    else:
        return '0'

