# This is a recursive algorithm
def max_level_group(group: str, level: int = 0) -> int:
    if len(group) < 2:  # Base case: If group is empty or only one item
        return level
    for i in range(len(group)):
        # If the character at the current position is a right parenthesis, recurse
        if group[i] == ")":
            return max(max_level_group(group[i + 1 :], level + 1), level)
        # If the character at the current position is a left parenthesis, recurse
        elif group[i] == "(":
            return max(max_level_group(group[:i], level + 1), level)
    return level
