def find_divisors(number: int, upper_bound: int) -> list:
    """ Given a positive integer, find all its divisors.
    It's possible to reduce the returned list to only odd or even divisors.
    If the number is prime, return None.
    >>> find_divisors(10, 15)
    [2, 5]
    """
    divisors = []
    if (number % 2 == 0):
        for j in range(2, upper_bound + 1, 2):
            if (upper_bound % j == 0):
                divisors.append(j)
    elif (number % 2 != 0):
        for j in range(2, upper_bound + 1):
            if (upper_bound % j == 0):
                divisors.append(j)
    return divisors

